import{_ as o,o as n,c as a,a3 as t}from"./chunks/framework.BK6ObQf6.js";const u=JSON.parse('{"title":"通过 Zone 连接多台机器","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/zones.md","filePath":"zh/guide/zones.md","lastUpdated":1794397216000}'),d={name:"zh/guide/zones.md"};function s(c,e,i,l,r,p){return n(),a("div",{"data-pagefind-body":!0},e[0]||(e[0]=[t(`<h1 id="通过-zone-连接多台机器" tabindex="-1">通过 Zone 连接多台机器 <a class="header-anchor" href="#通过-zone-连接多台机器" aria-label="Permalink to &quot;通过 Zone 连接多台机器&quot;">​</a></h1><p>Zone 是一组机器共享的虚拟 IPv4 网络。每台加入的机器都会获得一个网络地址， 应用可以通过本机 SOCKS5 代理访问其他成员；VLAN 模式下也可以直接使用成员的 虚拟地址。</p><p>Zone 默认为私有。私有 Zone 不会出现在任何列表中，只有拿到 Zone ID 的机器才能加入。 管理员可以创建公开 Zone：公开 Zone 会出现在网站的 <strong>Public zones</strong> 视图和 <code>linksocks zone list</code> 中，任何看到它的人都能加入，并访问成员对外开放的服务。</p><p>打开网站的 <a href="https://l.zetx.tech/zones" target="_blank" rel="noreferrer">Zones</a> 页面即可浏览公开 Zone、查看成员并复制 加入命令。浏览和加入都不需要账号；登录用户默认看到 <strong>My zones</strong>（自己创建的 Zone）， 可切换到 <strong>Public zones</strong>（全部公开 Zone），没有合并列表。Zone ID 为小写 UUID。</p><h2 id="连接前准备" tabindex="-1">连接前准备 <a class="header-anchor" href="#连接前准备" aria-label="Permalink to &quot;连接前准备&quot;">​</a></h2><ul><li>使用包含 <code>zone</code> 命令的 LinkSocks CLI。此功能没有 Python 库 API，安装 Python 绑定不会提供 <code>Zone</code> 类。</li><li>默认加入模式只需在本机运行 SOCKS5 代理，不需要特殊权限。可选的 <code>--vlan</code> 模式会创建 TAP 网卡，需要 root 或管理员权限，目前仅在 Linux 上可用。</li><li>Zone 网段不能与任何成员已有的局域网、VPN、容器网络或其他路由重叠。 客户端会检查网卡地址；Linux 还会检查所有 IPv4 路由表，默认路由除外。</li><li>代理模式支持 Linux、macOS 和 Windows。<code>--vlan</code> 需要 Linux，并依赖 <code>/dev/net/tun</code> 和 <code>ip</code> 命令。</li></ul><p>Linux 已使用真实 TAP 网卡和代理模式完成端到端验证。Windows 和 macOS 可以编译， 尚未在对应系统上验证。</p><p>代理模式传输 TCP 流和 UDP 数据报（SOCKS5 UDP ASSOCIATE），不创建网卡， 因此不支持 ICMP 等其他 IP 协议。<code>--vlan</code> 传输完整的以太网帧：ARP、ICMP/ping、 TCP、UDP、广播（UDP 广播、WOL 魔术包）、组播和原始以太网帧都能在成员之间 像在同一物理网段一样传输。VLAN 网卡 MTU 为 1500。</p><p>两种模式都不提供 IPv6、P2P 直连、DNS、局域网子网共享，也不会设置互联网默认路由。 请使用成员的虚拟 IP，代理模式下也可以使用成员名，不要依赖局域网自动发现。</p><h2 id="创建网络" tabindex="-1">创建网络 <a class="header-anchor" href="#创建网络" aria-label="Permalink to &quot;创建网络&quot;">​</a></h2><ol><li>打开 linksocks.js 网站的 <code>/zones</code> 页面并登录。</li><li>点击 <strong>Create zone</strong>。</li><li>填写 <strong>Zone name</strong>、<strong>IPv4 network (CIDR)</strong> 和 <strong>Member limit</strong>。</li><li>选择可见性：默认的 <strong>Private</strong>，或管理员可选的 <strong>Public</strong>。</li><li>点击 <strong>Create zone</strong>。</li></ol><p>名称长度为 1–64 个字符。整个网段必须位于 RFC1918 私有地址范围内： <code>10.0.0.0/8</code>、<code>172.16.0.0/12</code> 或 <code>192.168.0.0/16</code>。支持 <code>/16</code> 到 <code>/30</code> 前缀。成员上限为 2–256，且不能超过可用地址数：<code>/30</code> 可容纳 2 台，<code>/29</code> 可容纳 6 台，<code>/24</code> 可容纳 254 台。网络地址和广播地址不会分配给成员。</p><p>新建的 Zone 是私有的：不出现在任何列表中，只有你提供 ID 的机器才能加入。 只有管理员可以创建公开 Zone。公开 Zone 会出现在网站和 <code>linksocks zone list</code> 中，任何看到它的人都能加入并访问成员对外开放的服务；请谨慎分享 ID，并确认 每台成员机器的防火墙只放行需要暴露的服务。</p><p>登录用户可以创建 Zone，并删除自己创建的 Zone。管理员可以删除任意 Zone。 删除 Zone 会断开所有成员并释放全部地址，且无法撤销。</p><h2 id="让每台机器加入" tabindex="-1">让每台机器加入 <a class="header-anchor" href="#让每台机器加入" aria-label="Permalink to &quot;让每台机器加入&quot;">​</a></h2><ol><li>在 <code>/zones</code> 找到目标网络，点击 <strong>Copy command</strong>。公开 Zone 的 ID 和命令 默认遮盖，需要先勾选确认已检查本机防火墙；点击 <strong>Copy command</strong> 也会先弹出 该警告。浏览器不允许自动复制时，命令会被选中，按 Ctrl+C 即可手动复制。</li><li>在每台机器上执行复制的命令。代理模式不需要提升权限；<code>--vlan</code> 需要 root。 保持命令运行。终端的 <code>Joined</code> 行会显示分配的虚拟 IP、VLAN 模式下的网卡 名称和在线对端数量。</li><li>用应用连接成员的虚拟 IP，代理模式下也可以使用成员名。VLAN 模式下服务 需要监听虚拟 IP，代理模式下服务监听本机回环即可；两者都需要防火墙允许该连接。</li></ol><p>加入命令接受小写的 Zone UUID。<code>--name</code> 可以修改成员列表中显示的机器名称， 默认使用主机名。</p><h3 id="代理模式-默认" tabindex="-1">代理模式（默认） <a class="header-anchor" href="#代理模式-默认" aria-label="Permalink to &quot;代理模式（默认）&quot;">​</a></h3><p><code>linksocks zone join &lt;zone-id&gt;</code> 会在本机 <code>127.0.0.1:6080</code> 启动 SOCKS5 代理， 并输出代理地址：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SOCKS5 proxy listening on 127.0.0.1:6080</span></span></code></pre></div><p>用 <code>--socks-port</code> 修改端口；<code>--socks-port 0</code> 关闭监听。应用通过虚拟 IP 或成员名 寻址，并应让代理解析名称：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --socks5-hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:6080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://10.88.0.2:8080/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --socks5-hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:6080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://machine-b:8080/</span></span></code></pre></div><p>代理模式支持 TCP 和 UDP（SOCKS5 UDP ASSOCIATE）。连接成员虚拟 IP 的流量会到达 对方监听在 <code>127.0.0.1</code> 上的服务，因此不需要公网网卡或入站端口。由于没有网卡， 除 TCP、UDP 之外的协议不会被传输。</p><h3 id="vlan-模式-vlan" tabindex="-1">VLAN 模式（<code>--vlan</code>） <a class="header-anchor" href="#vlan-模式-vlan" aria-label="Permalink to &quot;VLAN 模式（\`--vlan\`）&quot;">​</a></h3><p>使用 <code>--vlan</code> 时，客户端创建二层 TAP 网卡（默认名 <code>lz0</code>，可用 <code>--interface</code> 改名），MTU 为 1500。成员就像同一个以太网段中的主机：ARP、ICMP/ping、TCP、UDP、 UDP 广播、WOL 魔术包、组播和原始以太网帧都能在成员之间传输。应用直接连接成员的 虚拟 IP，无需配置代理。VLAN 模式下额外指定 <code>--socks-port</code> 也会启动 SOCKS5 监听。</p><p>在同一台机器加入多个 Zone 时，每个加入进程应使用不同网卡名称，且各网段不能重叠。</p><h3 id="windows-和-macos" tabindex="-1">Windows 和 macOS <a class="header-anchor" href="#windows-和-macos" aria-label="Permalink to &quot;Windows 和 macOS&quot;">​</a></h3><p><code>--vlan</code> 需要一块二层（以太网）虚拟网卡。LinkSocks 只在 Linux 上创建它； Windows 和 macOS 上请不加 <code>--vlan</code>，使用 SOCKS5 代理——不需要驱动，也不需要 管理员权限，可以按虚拟 IP 或成员名访问成员。</p><p>在这两个系统上做二层是有代价的：Zone 协议把每台成员的网卡 MAC 当作它在网段里的 身份（接收时按它过滤），因此客户端无法掌控其 MAC 的网卡无法承载这些流量。</p><ul><li><strong>Windows</strong>：需要 TAP-Windows6 这类二层驱动，并以管理员权限安装、把网卡 MAC 设为本机的成员 MAC；或者等一个基于 Wintun 的 IP 包模式——它放弃 ARP、广播和 非 IP 协议，但无需配置 MAC。</li><li><strong>macOS</strong>：系统只提供三层隧道（utun），同样要等 IP 包模式；目前只能用代理。</li></ul><p>在 WSL2 里（它本身就是 Linux）<code>--vlan</code> 对 WSL 内运行的程序有效。Windows 程序 仍然无法加入该网段：请让它们使用代理，WSL2 会把监听在 <code>127.0.0.1</code> 的代理转发出来。</p><h3 id="命令和参数" tabindex="-1">命令和参数 <a class="header-anchor" href="#命令和参数" aria-label="Permalink to &quot;命令和参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令或参数</th><th>用途</th></tr></thead><tbody><tr><td><code>zone list</code></td><td>列出公开 Zone 的 ID、名称、网段和成员上限</td></tr><tr><td><code>zone join &lt;zone-id&gt;</code></td><td>在前台加入；启动 SOCKS5 代理，或配合 <code>--vlan</code> 创建 TAP 网卡</td></tr><tr><td><code>zone leave &lt;zone-id&gt;</code></td><td>释放本机地址，并停止正在运行的加入进程</td></tr><tr><td><code>--url</code>、<code>-u</code></td><td>协调服务网站地址，默认为 <code>https://l.zetx.tech</code></td></tr><tr><td><code>--identity</code></td><td>本地机器密钥路径；加入和退出必须使用同一文件</td></tr><tr><td><code>--name</code></td><td>加入时显示的机器名称，默认使用主机名</td></tr><tr><td><code>--socks-port</code></td><td>本机 SOCKS5 代理端口，默认 <code>6080</code>；<code>0</code> 关闭监听；配合 <code>--vlan</code> 时只有显式指定才启动代理</td></tr><tr><td><code>--vlan</code></td><td>不使用代理模式，改为创建二层 TAP 网卡（Linux，需要 root）</td></tr><tr><td><code>--interface</code></td><td><code>--vlan</code> 使用的 TAP 网卡名称，默认 <code>lz0</code></td></tr><tr><td><code>--no-env-proxy</code>、<code>-E</code></td><td>忽略环境变量中的代理设置</td></tr><tr><td><code>--ech</code></td><td>连接协调服务时的 Encrypted Client Hello，默认 <code>auto</code></td></tr><tr><td><code>--debug</code>、<code>-d</code></td><td>输出调试日志；<code>-dd</code> 追加 trace 日志（流、数据报、防火墙丢弃、协调服务心跳）</td></tr></tbody></table><p>这些子命令均在 <code>linksocks</code> 下运行。<code>--url</code> 接受 HTTP(S) 和 WebSocket 地址， 加入后日志会记录：加入过程与分配到的地址、之后的对端数量变化、SOCKS5 监听， 以及 VLAN 模式下的网卡。加 <code>-d</code> 可以看到流量为何通或不通——流已建立、被拒绝 及其原因（被 Zone 防火墙拦截、对端不在线、本机服务不可达）——加 <code>-dd</code> 则记录 数据报、防火墙丢弃等逐帧细节。</p><p>连接远端协调服务时使用 HTTPS。<code>--name</code>、<code>--socks-port</code>、<code>--vlan</code> 和 <code>--interface</code> 只用于 <code>join</code>，表中其他参数为各 Zone 子命令共用。</p><h2 id="管理-zone" tabindex="-1">管理 Zone <a class="header-anchor" href="#管理-zone" aria-label="Permalink to &quot;管理 Zone&quot;">​</a></h2><p>Zone 所有者和网站管理员可以在 <code>/zones</code> 管理成员和设置：</p><ul><li><strong>View members</strong> 显示每台机器的名称、状态、虚拟 IP 和身份。在线机器可以 <strong>Kick</strong>，保留地址的离线机器可以 <strong>Remove</strong>。两种操作都会立即断开正在运行的 加入并释放地址。被移除的进程会输出 <code>Removed from the zone.</code> 后退出，不会自动 重连；再次运行加入命令即可重新加入。</li><li><strong>Settings</strong> 可以修改 <strong>欢迎语</strong> 和 <strong>防火墙规则</strong>。欢迎语最长 512 个字符， 成员加入时会在其终端显示。</li><li>每个 Zone 最多 64 条防火墙规则，按顺序匹配。每条规则包含源和目的 IPv4 网段、 源和目的端口（any、单个端口或区间）、协议（<code>any</code>、<code>tcp</code>、<code>udp</code>、<code>icmp</code>、<code>arp</code>） 以及允许或拒绝动作。命中第一条匹配的规则即生效；没有匹配任何规则的流量按 Zone 的默认策略处理（allow 或 deny）。</li></ul><p>两种模式的规则执行方式不同。代理模式下，中继和连接两端都会按规则检查每个 TCP 连接和 UDP 数据报。<code>--vlan</code> 模式下中继看不到以太网帧的内容，由接收端成员用 本机的规则副本过滤每个帧。带具体源端口的规则只对 VLAN 流量生效，因为代理模式的 流没有源端口可供匹配。</p><h2 id="保留本机身份" tabindex="-1">保留本机身份 <a class="header-anchor" href="#保留本机身份" aria-label="Permalink to &quot;保留本机身份&quot;">​</a></h2><p>首次加入会在本地生成 Ed25519 身份密钥，私钥始终保存在机器上。默认文件为系统用户 配置目录下的 <code>linksocks/zone.key</code>。配置目录通常为 Linux 的 <code>~/.config</code>、 macOS 的 <code>~/Library/Application Support</code> 和 Windows 的 <code>%AppData%</code>。</p><p>在 Unix 上，客户端以 <code>0600</code> 权限创建密钥文件，以 <code>0700</code> 权限创建缺失的父目录， 并拒绝使用授予用户组或其他用户任何权限的已有密钥文件。Windows 请通过文件访问控制限制权限。 不要把同一份身份密钥复制给多台机器：一个 Zone 只允许同一身份有一个在线连接。</p><p>需要在提升权限后使用固定文件位置时，请通过 <code>--identity</code> 指定绝对路径。 更换运行用户或密钥文件会改变机器身份。保留原始密钥，才能恢复保留的地址或主动释放它。</p><p>VLAN 模式下网卡的 MAC 地址由该身份派生，重连后保持不变，因此对端的 ARP 缓存仍然有效。</p><h2 id="退出或恢复连接" tabindex="-1">退出或恢复连接 <a class="header-anchor" href="#退出或恢复连接" aria-label="Permalink to &quot;退出或恢复连接&quot;">​</a></h2><p>在加入命令的终端按 <strong>Ctrl+C</strong>，即可退出并释放地址。也可以在另一个终端运行 <code>zone leave</code>，使用相同的 Zone ID、协调服务地址和身份文件。这会同时断开另一个 进程中运行的加入连接。以后再次加入时，地址可能改变。</p><p>网络中断或进程异常退出后，网站会将机器标记为 <strong>Offline</strong>，保留地址 24 小时。 离线保留地址仍占用成员名额。加入进程遇到网络故障会自动重连；保留期内用同一身份 重启，也会恢复原地址。主动退出会立即释放地址。被所有者或管理员移除的机器会停止 运行，不会自动重连。</p><p>删除 Zone 会断开所有成员并释放全部地址，且无法撤销。需要删除时，在 <code>/zones</code> 点击 <strong>Delete zone</strong> 并确认。Zone 被删除或成员被主动移除后，客户端会停止运行。</p><h2 id="了解加密范围" tabindex="-1">了解加密范围 <a class="header-anchor" href="#了解加密范围" aria-label="Permalink to &quot;了解加密范围&quot;">​</a></h2><p>每次连接都会生成新的 X25519 交换密钥，成员之间使用 XChaCha20-Poly1305 加密数据包。 重连后会更换交换密钥。协调服务提供正确的成员目录时，中继只能转发加密载荷，无法读取内容。</p><p>机器身份、对端公钥和地址分配依赖可信的协调服务。此机制不能防止恶意协调服务替换 成员目录。协调服务可以看到成员信息、虚拟源 IP 和目标 IP、数据包大小与传输时间； VLAN 模式下还能看到所转发以太网帧的地址。</p><h2 id="排查连接问题" tabindex="-1">排查连接问题 <a class="header-anchor" href="#排查连接问题" aria-label="Permalink to &quot;排查连接问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>提示或现象</th><th>检查方法</th></tr></thead><tbody><tr><td><code>administrator privileges required</code></td><td><code>--vlan</code> 需要 root；使用提升权限的终端运行，并确认 <code>/dev/net/tun</code> 存在</td></tr><tr><td><code>zone --vlan currently requires Linux</code></td><td>VLAN 模式仅支持 Linux；其他系统请使用代理模式</td></tr><tr><td><code>configure zone interface</code></td><td>确认系统网络命令存在，且有权执行</td></tr><tr><td><code>Note: --interface applies to --vlan mode</code></td><td>代理模式下请去掉 <code>--interface</code>；需要 TAP 网卡时加上 <code>--vlan</code></td></tr><tr><td><code>overlaps</code></td><td>选择不与提示中的网卡或路由重叠的 Zone 网段</td></tr><tr><td><code>Identity is already online</code></td><td>停止同一身份的另一个加入进程，或先用其密钥执行 <code>zone leave</code></td></tr><tr><td><code>Zone is full</code></td><td>离线地址也占名额；由对应机器主动退出，或等待 24 小时保留期结束</td></tr><tr><td><code>Zone not found</code></td><td>Zone 已被删除或 ID 有误；从同一网站复制 ID 和地址</td></tr><tr><td><code>Zone service is not configured</code></td><td>服务部署者需要配置 Worker 的 <code>DB</code>、<code>ZONE</code> 绑定，参见 <a href="https://github.com/linksocks/linksocks.js/blob/main/README.cn.md#zone-%E8%99%9A%E6%8B%9F%E7%BD%91%E7%BB%9C" target="_blank" rel="noreferrer">Worker 部署说明</a></td></tr><tr><td><code>Removed from the zone.</code></td><td>被所有者或管理员移除；再次运行加入命令可以重新加入，或联系对方</td></tr><tr><td>通过代理连接被拒绝</td><td>与 Zone 所有者确认防火墙规则和默认策略</td></tr><tr><td>已加入，但应用无法连接</td><td>确认对端在线、目标是其虚拟 IP 或成员名，且 SOCKS 客户端使用远程名称解析（<code>--socks5-hostname</code>）；VLAN 模式下确认服务监听虚拟 IP，且本机防火墙放行访问</td></tr></tbody></table><h2 id="linux-实测记录" tabindex="-1">Linux 实测记录 <a class="header-anchor" href="#linux-实测记录" aria-label="Permalink to &quot;Linux 实测记录&quot;">​</a></h2><p>以下输出来自通过本地 Worker 连接的两个 Linux 网络命名空间，使用 <code>/29</code> 网段， 成员上限为 6。其中一次运行验证默认代理模式，另一次使用 <code>--vlan</code> 和真实 TAP 网卡， 覆盖了 ARP、ICMP、TCP、UDP、重连和退出。验证结束后已删除测试 Zone，使用时请从 网站复制你自己的加入命令。</p><h3 id="使用真实-tap-网卡的-vlan-模式" tabindex="-1">使用真实 TAP 网卡的 VLAN 模式 <a class="header-anchor" href="#使用真实-tap-网卡的-vlan-模式" aria-label="Permalink to &quot;使用真实 TAP 网卡的 VLAN 模式&quot;">​</a></h3><p>两个加入进程分别输出：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Joined Zone network test (9b89a4eb-8dff-4a3f-acab-2f192349d9a1, private) as 10.249.231.1 on lz0; 0 peer(s) online.</span></span>
<span class="line"><span>Joined Zone network test (9b89a4eb-8dff-4a3f-acab-2f192349d9a1, private) as 10.249.231.2 on lz0; 1 peer(s) online.</span></span></code></pre></div><p>ARP 解析、达到网卡 MTU 的 ICMP 测试、TCP 传输和 UDP 回显均成功：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PING 10.249.231.2 (10.249.231.2) 1472(1500) bytes of data.</span></span>
<span class="line"><span>1480 bytes from 10.249.231.2: icmp_seq=1 ttl=64 time=0.938 ms</span></span>
<span class="line"><span>1480 bytes from 10.249.231.2: icmp_seq=2 ttl=64 time=0.775 ms</span></span>
<span class="line"><span>1480 bytes from 10.249.231.2: icmp_seq=3 ttl=64 time=0.687 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- 10.249.231.2 ping statistics ---</span></span>
<span class="line"><span>3 packets transmitted, 3 received, 0% packet loss, time 2055ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 0.687/0.800/0.938/0.103 ms</span></span>
<span class="line"><span>TCP: 262144 bytes, SHA-256 81d0141af58569f91edf2d036b67a6b82c062d1829fd93aec50ed96b4773d225</span></span>
<span class="line"><span>UDP: 1200-byte echo verified.</span></span></code></pre></div><p>第二台机器异常退出后，使用原身份重新加入，保留了原地址。ICMP 的拒绝规则一度 拦截了 ping，清除规则后恢复。随后主动退出命令停止了正在运行的加入进程，并释放了地址：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rejoin retained 10.249.231.2.</span></span>
<span class="line"><span>Firewall: an ICMP deny rule stopped pings in VLAN mode.</span></span>
<span class="line"><span>Firewall: clearing the rule restored pings.</span></span>
<span class="line"><span>Left zone 9b89a4eb-8dff-4a3f-acab-2f192349d9a1.</span></span>
<span class="line"><span>Leave disconnected the running machine and released its IPv4 lease.</span></span>
<span class="line"><span>Signal-driven leave removed the final membership.</span></span>
<span class="line"><span>PASS: real TAP Ethernet (ARP), ICMP, TCP, UDP, reconnect and leave.</span></span></code></pre></div><h3 id="代理模式" tabindex="-1">代理模式 <a class="header-anchor" href="#代理模式" aria-label="Permalink to &quot;代理模式&quot;">​</a></h3><p>两台成员通过本地 Worker 加入同一 Zone，机器 B 在回环上提供 TCP 和 UDP 服务。 机器 A 的 SOCKS5 客户端分别通过虚拟 IP 和成员名访问成功；一条拒绝规则一度拦截了 新的 TCP 连接，清除后恢复：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SOCKS5 proxy listening on 127.0.0.1:20485</span></span>
<span class="line"><span>TCP: curl --socks5-hostname reached machine-b by virtual IP and by name.</span></span>
<span class="line"><span>UDP: echoed 16 bytes through SOCKS5 UDP ASSOCIATE.</span></span>
<span class="line"><span>Firewall: a deny rule stopped a new TCP connection through the proxy.</span></span>
<span class="line"><span>Firewall: clearing the rule restored access.</span></span>
<span class="line"><span>PASS: proxy-mode SOCKS5 TCP and UDP between two members.</span></span></code></pre></div>`,65)]))}const g=o(d,[["render",s]]);export{u as __pageData,g as default};
